// Package datasets embeds the benchmark datasets (generated by cmd/datasets).
package datasets

import (
	"bufio"
	"embed"
	"encoding/json"
	"sort"
)

//go:embed *.jsonl *.options.json
var files embed.FS

// Example is one row of a dataset. State is passed to the model as is (string or object).
type Example struct {
	ID    int             `json:"id"`
	State json.RawMessage `json:"state"`
	Label string          `json:"label"`
}

// Option is one answer option with an optional description (empty = none).
type Option struct {
	Name        string
	Description string
}

// Dataset holds the options and the calibration / test splits.
type Dataset struct {
	Name         string
	Instructions string
	Options      []Option
	Calibration  []Example
	Test         []Example
}

var (
	Emotion   = load("emotion", "Which emotion does the author of this text express?")
	XNLI      = load("xnli", "What is the relation between the premise and the hypothesis?")
	MASSIVE   = load("massive", "Which intent does this voice assistant command express?")
	Banking77 = load("banking77", "Which banking intent does this customer message express?")
	CLINC150  = load("clinc150", "Which intent does this user utterance express?")
	BFCL      = load("bfcl", "Which function should be called to fulfil this request?")

	All = []Dataset{Emotion, XNLI, MASSIVE, Banking77, CLINC150, BFCL}
)

// ByName returns the dataset with the given name, or false.
func ByName(name string) (Dataset, bool) {
	for _, d := range All {
		if d.Name == name {
			return d, true
		}
	}
	return Dataset{}, false
}

func load(name, instructions string) Dataset {
	return Dataset{
		Name:         name,
		Instructions: instructions,
		Options:      options(name + ".options.json"),
		Calibration:  examples(name + ".calibration.jsonl"),
		Test:         examples(name + ".test.jsonl"),
	}
}

func options(file string) []Option {
	b, err := files.ReadFile(file)
	if err != nil {
		panic(err)
	}
	var m map[string]*string
	if err := json.Unmarshal(b, &m); err != nil {
		panic(err)
	}

	var out []Option
	for name, desc := range m {
		o := Option{Name: name}
		if desc != nil {
			o.Description = *desc
		}
		out = append(out, o)
	}

	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func examples(file string) []Example {
	f, err := files.Open(file)
	if err != nil {
		panic(err)
	}
	defer f.Close()
	var out []Example
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	for sc.Scan() {
		var e Example
		if err := json.Unmarshal(sc.Bytes(), &e); err != nil {
			panic(err)
		}
		out = append(out, e)
	}

	if err := sc.Err(); err != nil {
		panic(err)
	}

	return out
}

// WithoutDescriptions returns the dataset with option descriptions removed and
// "-nodesc" appended to the name (tests how much the descriptions matter).
func WithoutDescriptions(ds Dataset) Dataset {
	out := ds
	out.Name = ds.Name + "-nodesc"
	out.Options = nil
	for _, o := range ds.Options {
		out.Options = append(out.Options, Option{Name: o.Name})
	}
	return out
}
